}

message IntrospectRequest {
  string token = 1;
}
message IntrospectResponse {
  string principal_prn = 1;
  string status = 2; // principal status
  string issuer = 3;
  string subject = 4;
  google.protobuf.Timestamp expires_at = 5;
  repeated Membership memberships = 6; // reuse tenancy message
  reserved 7;
  reserved "role_group_prns";
  repeated RoleGrantRef role_grants = 8;
}
message RoleGrantRef {
  string scope_prn = 1;
  string role_key = 2;
}

message IntrospectApiKeyRequest {
  string token = 1;
}
message IntrospectApiKeyResponse {
  string principal_prn = 1;
  string status = 2; // principal status
  string key_id = 3;
  google.protobuf.Timestamp expires_at = 4;
  repeated Membership memberships = 5; // reuse tenancy message
  repeated RoleGrantRef role_grants = 6;
}

service TenancyService {
  rpc CreateOrganization(CreateOrganizationRequest) returns (CreateOrganizationResponse);
  rpc GetOrganization(GetOrganizationRequest) returns (GetOrganizationResponse);
  rpc ListOrganizations(ListOrganizationsRequest) returns (ListOrganizationsResponse);
  rpc RenameOrganization(RenameOrganizationRequest) returns (RenameOrganizationResponse);
  rpc ArchiveOrganization(ArchiveOrganizationRequest) returns (ArchiveOrganizationResponse);
  rpc RestoreOrganization(RestoreOrganizationRequest) returns (RestoreOrganizationResponse);
  rpc CreateTeam(CreateTeamRequest) returns (CreateTeamResponse);
  rpc GetTeam(GetTeamRequest) returns (GetTeamResponse);
  rpc ListTeams(ListTeamsRequest) returns (ListTeamsResponse);
  rpc RenameTeam(RenameTeamRequest) returns (RenameTeamResponse);
  rpc ArchiveTeam(ArchiveTeamRequest) returns (ArchiveTeamResponse);
  rpc RestoreTeam(RestoreTeamRequest) returns (RestoreTeamResponse);
  rpc CreateProject(CreateProjectRequest) returns (CreateProjectResponse);
  rpc GetProject(GetProjectRequest) returns (GetProjectResponse);
  rpc ListProjects(ListProjectsRequest) returns (ListProjectsResponse);
  rpc RenameProject(RenameProjectRequest) returns (RenameProjectResponse);
  rpc ArchiveProject(ArchiveProjectRequest) returns (ArchiveProjectResponse);
  rpc RestoreProject(RestoreProjectRequest) returns (RestoreProjectResponse);
  rpc AttachMembership(AttachMembershipRequest) returns (AttachMembershipResponse);
  // Detaching an ORG membership also removes that principal's team/project
  // memberships in that same org (cascade detach, spec §5.1 rule 5).
  rpc DetachMembership(DetachMembershipRequest) returns (DetachMembershipResponse);
  rpc ListMemberships(ListMembershipsRequest) returns (ListMembershipsResponse);
}

service AuthnService {
  rpc Introspect(IntrospectRequest) returns (IntrospectResponse);
  rpc IntrospectApiKey(IntrospectApiKeyRequest) returns (IntrospectApiKeyResponse);
}

message IsAuthorizedRequest {
  string principal_prn = 1;
  string action = 2;
  string resource_prn = 3;
  map<string, string> context = 4;
}

