383	    /// `list_by_principal` fake: a plain, insertion-ordered map keyed by principal uuid —
384	    /// mirrors `authenticate_token.rs`'s own `InMemoryMemberships` test fake. The other
385	    /// `MembershipRepository` methods are unused by `AuthenticateApiKey` (only ever calls
386	    /// `list_by_principal`) and panic if invoked.
387	    #[derive(Default)]
388	    struct InMemoryMemberships {
389	        rows: Mutex<HashMap<Uuid, Vec<MembershipRecord>>>,
390	    }
391	
392	    impl InMemoryMemberships {
393	        fn seed(&self, principal: Uuid, count: usize) {
394	            let now = epoch();
395	            let mut rows = self.rows.lock().unwrap();
396	            let entry = rows.entry(principal).or_default();
397	            for i in 0..count {
398	                entry.push(MembershipRecord {
399	                    id: Uuid::from_u128(i as u128 + 1),
400	                    principal_prn: format!("prn:pgs:iam:::principal/{principal}"),
401	                    node_prn: format!("prn:pgs:iam:::organization/{i}"),
402	                    created_at: now,
403	                });
404	            }
405	        }
406	    }
