410	        async fn attach(&self, _membership: &paigasus_iam_core::Membership) -> Result<MembershipRecord, RepositoryError> {
411	            unimplemented!("AuthenticateApiKey never calls attach")
412	        }
413	        async fn find(&self, _id: Uuid) -> Result<Option<MembershipRecord>, RepositoryError> {
414	            unimplemented!("AuthenticateApiKey never calls find")
415	        }
416	        async fn detach(&self, _id: Uuid) -> Result<(), RepositoryError> {
417	            unimplemented!("AuthenticateApiKey never calls detach")
418	        }
419	        async fn list_by_principal(&self, principal: Uuid, limit: u64, offset: u64) -> Result<Vec<MembershipRecord>, RepositoryError> {
420	            let rows = self.rows.lock().unwrap();
421	            let items = rows.get(&principal).cloned().unwrap_or_default();
422	            Ok(items.into_iter().skip(offset as usize).take(limit as usize).collect())
423	        }
424	        async fn list_by_node(&self, _node: &TenancyNodeRef, _limit: u64, _offset: u64) -> Result<Vec<MembershipRecord>, RepositoryError> {
425	            unimplemented!("AuthenticateApiKey never calls list_by_node")
426	        }
427	    }
