1	// SPDX-License-Identifier: Apache-2.0
2	
3	//! API-key introspection cache (spec §9/D5): a positive-validation cache keyed by `keyid`,
4	//! sitting in front of the Postgres source of truth on `AuthenticateApiKey`'s hot path (parse
5	//! token → `cache.get(keyid)` → hit re-verifies the secret + re-checks expiry + cached
6	//! `sa_status`, miss falls through to a DB validate + `cache.put`). [`CachedValidation`] carries
7	//! only what's needed to rebuild an `AuthnPrincipal`, re-check expiry, and re-verify the
8	//! presented secret on read: the resolved principal id, the SA status, the key expiry, and the
9	//! stored peppered HMAC hash (`key_hash`) — **never** the plaintext secret. Keying by `keyid`
10	//! (a non-secret token segment) is what makes eviction on revoke/archive work; caching the
11	//! `key_hash` alongside is what stops that same non-secret key from authenticating WITHOUT the
12	//! secret — the caller MUST `SecretHasher::verify` the presented secret against `key_hash` on
13	//! every hit (that check is the credential; the `keyid` is only the lookup key).
14	//!
15	//! Two implementations, mirroring `adapters::authz::decision_cache` exactly: [`MemoryApiKeyCache`]
16	//! (single-replica, TTL-bounded `Mutex<HashMap<..>>`) and [`RedisApiKeyCache`] (cross-replica,
17	//! `ConnectionManager`, same connect/clone-per-call pattern as `RedisDecisionCache`/`SliceCache`).
18	//!
19	//! **Both fail OPEN (D5):** this cache is a pure accelerator over the Postgres-backed
20	//! `ApiKeyRepository` — never the system of record — so a `get` that can't be served cleanly (a
21	//! Redis error, or a payload that fails to deserialize) is reported as a plain cache miss,
22	//! `None`, never an error; a `put`/`evict` that can't be written is logged and swallowed. A
23	//! Redis outage bypasses the accelerator; it must never fail (or falsely succeed) a validation.
24	//!
25	//! **Revocation-vs-cache honesty (challenge M5, spec §9):** `MemoryApiKeyCache` evicts only the
26	//! local replica's entries — it is single-replica/dev only; multi-replica (HA) deployments must
27	//! use [`RedisApiKeyCache`] so `RevokeApiKey`/`ArchiveServiceAccount` evictions are global. Even
28	//! on Redis, a put-after-evict race (a concurrent `resolve` that DB-validated *before* a revoke
29	//! and `put`s *after* the evict) can re-seed a positive entry for up to one TTL — hence the
30	//! short default TTL (30s). This cache never re-checks `expires_at` itself on a hit; that's the
31	//! caller's job against the cached value (expiry has no staleness problem — it's recomputed
32	//! fresh from `CachedValidation.expires_at` on every read).
33	
34	use async_trait::async_trait;
35	use base64::Engine;
36	use base64::engine::general_purpose::STANDARD;
37	use chrono::{DateTime, Utc};
38	use paigasus_iam_core::{ApiKeyId, PrincipalId, PrincipalStatus};
39	use paigasus_kernel::Prn;
40	use redis::aio::ConnectionManager;
41	use redis::{AsyncCommands, Client};
42	use serde::{Deserialize, Serialize};
43	use std::collections::HashMap;
44	use std::sync::Mutex;
45	use std::time::{Duration, Instant};
46	
47	/// Redis/in-proc key prefix (spec §9): `iam:apikey:<keyid>`.
48	const KEY_PREFIX: &str = "iam:apikey:";
49	
50	fn cache_key(key_id: ApiKeyId) -> String {
51	    format!("{KEY_PREFIX}{key_id}")
52	}
53	
54	/// Enough of a validated API key to rebuild an `AuthnPrincipal`, re-check expiry, AND
55	/// re-verify the presented secret on a cache hit (spec §9). Carries the resolved principal id,
56	/// the service account's current status, the key's own expiry, and `key_hash` — the SAME
57	/// peppered HMAC-SHA-256 tag stored in Postgres (`ApiKeyRepository::find_by_id`'s second
58	/// return), NOT the plaintext secret and NOT a new secret. Caching the stored hash is what lets
59	/// `AuthenticateApiKey`'s hit path skip the two DB round-trips (`find_by_id` + `find_principal`)
60	/// while STILL constant-time-verifying the presented secret against it on EVERY hit — a hit
61	/// keyed by `key_id` alone (a non-secret token segment) must never authenticate on the `key_id`
62	/// without also proving possession of the secret. A Redis leak of the hash can't validate keys
63	/// without the operator's pepper (which never leaves the process), so the hash is safe to cache.
64	#[derive(Debug, Clone, PartialEq, Eq)]
65	pub struct CachedValidation {
66	    pub principal_id: PrincipalId,
67	    pub sa_status: PrincipalStatus,
68	    pub expires_at: Option<DateTime<Utc>>,
69	    pub key_hash: Vec<u8>,
70	}
71	
72	/// The Redis wire payload for [`CachedValidation`]. `PrincipalId`/`PrincipalStatus` are pure
73	/// domain value types with no `serde` impls (core-crate purity, ADR-0005), so they're carried
74	/// as their string forms (`PrincipalId::canonical()` / `PrincipalStatus::as_str()`) and
75	/// reconstructed on read; `expires_at` is `chrono::DateTime<Utc>`, which already round-trips
76	/// via the workspace's `chrono/serde` feature (see `adapters::oidc::jwks::CachedJwks`); the raw
77	/// `key_hash` bytes are carried as standard base64 (`chrono/serde` won't serialize a bare
78	/// `Vec<u8>` compactly, and base64 mirrors how `pg_api_keys.rs` already stores the hash as text).
79	#[derive(Serialize, Deserialize)]
80	struct WireValidation {
81	    principal_prn: String,
82	    sa_status: String,
83	    expires_at: Option<DateTime<Utc>>,
84	    key_hash: String,
85	}
86	
87	impl From<&CachedValidation> for WireValidation {
88	    fn from(v: &CachedValidation) -> Self {
89	        WireValidation {
90	            principal_prn: v.principal_id.canonical(),
91	            sa_status: v.sa_status.as_str().to_string(),
92	            expires_at: v.expires_at,
93	            key_hash: STANDARD.encode(&v.key_hash),
94	        }
95	    }
96	}
97	
98	impl TryFrom<WireValidation> for CachedValidation {
99	    type Error = ();
100	
101	    fn try_from(w: WireValidation) -> Result<Self, Self::Error> {
102	        let prn = Prn::parse(&w.principal_prn).map_err(|_| ())?;
103	        let sa_status = PrincipalStatus::parse(&w.sa_status).ok_or(())?;
104	        let key_hash = STANDARD.decode(&w.key_hash).map_err(|_| ())?;
105	        Ok(CachedValidation {
106	            principal_id: PrincipalId::from_prn(prn),
107	            sa_status,
108	            expires_at: w.expires_at,
109	            key_hash,
110	        })
111	    }
112	}
113	
114	/// Per-`keyid` positive-validation cache (spec §9/D5). `get`/`put` are infallible by design
115	/// (fail-open, see module docs) so `AuthenticateApiKey.resolve` never has to special-case a
116	/// cache backend failure.
117	#[async_trait]
118	pub trait ApiKeyValidationCache: Send + Sync {
119	    /// Looks up `key_id`. Fail-open: any backend error (Redis unreachable, payload that fails
120	    /// to deserialize) degrades to `None`, indistinguishable from "never cached" — the caller
121	    /// always falls through to a real DB validation on a miss.
122	    async fn get(&self, key_id: ApiKeyId) -> Option<CachedValidation>;
123	
124	    /// Caches `v` for `key_id`. Fail-open: any backend error is logged and swallowed — a
125	    /// failed `put` never fails the validation that produced `v`.
126	    async fn put(&self, key_id: ApiKeyId, v: &CachedValidation);
127	
128	    /// Evicts `key_id`, e.g. on `RevokeApiKey`/`ArchiveServiceAccount`. Fail-open: any backend
129	    /// error is logged and swallowed.
130	    async fn evict(&self, key_id: ApiKeyId);
131	}
132	
133	/// In-process `ApiKeyValidationCache`: a TTL-bounded `Mutex<HashMap<..>>` — single-replica,
134	/// dev/single-node posture only (spec §9 challenge M5: `RevokeApiKey`/`ArchiveServiceAccount`
135	/// evictions here are local-replica only; HA deployments must use [`RedisApiKeyCache`] so
136	/// eviction is global).
137	pub struct MemoryApiKeyCache {
138	    ttl: Duration,
139	    entries: Mutex<HashMap<ApiKeyId, (CachedValidation, Instant)>>,
140	}
141	
142	impl MemoryApiKeyCache {
143	    /// `ttl_secs` bounds how long a `put` entry stays servable before `get` treats it as a
144	    /// miss and drops it — the same freshness bound `RedisApiKeyCache` gets from Redis's own
145	    /// `EX` expiry.
146	    #[must_use]
147	    pub fn new(ttl_secs: u64) -> Self {
148	        Self {
149	            ttl: Duration::from_secs(ttl_secs),
150	            entries: Mutex::new(HashMap::new()),
151	        }
152	    }
153	}
154	
155	#[async_trait]
156	impl ApiKeyValidationCache for MemoryApiKeyCache {
157	    async fn get(&self, key_id: ApiKeyId) -> Option<CachedValidation> {
158	        let mut entries = self.entries.lock().unwrap();
159	        match entries.get(&key_id) {
160	            Some((value, expires_at)) if *expires_at > Instant::now() => Some(value.clone()),
161	            Some(_) => {
162	                // Expired: drop it eagerly so a stale entry never leaks past its own TTL even
163	                // if nothing else evicts it first.
164	                entries.remove(&key_id);
165	                None
166	            }
167	            None => None,
168	        }
169	    }
170	
171	    async fn put(&self, key_id: ApiKeyId, v: &CachedValidation) {
172	        let expires_at = Instant::now() + self.ttl;
173	        self.entries.lock().unwrap().insert(key_id, (v.clone(), expires_at));
174	    }
175	
176	    async fn evict(&self, key_id: ApiKeyId) {
177	        self.entries.lock().unwrap().remove(&key_id);
178	    }
179	}
180	
181	/// `ApiKeyValidationCache` backed by Redis via an auto-reconnecting `ConnectionManager` (spec
182	/// §9), mirroring `adapters::authz::decision_cache::RedisDecisionCache`. Cheap to clone the
183	/// connection per call — `ConnectionManager` is itself `Arc`-backed and designed for
184	/// concurrent callers.
185	///
186	/// **Fail-open (D5):** every error path (connect, I/O, or (de)serialize) on `get` returns
187	/// `None` — a plain miss — and every error on `put`/`evict` is logged and swallowed. The
188	/// caller always falls through to a real DB validation on a miss, so a Redis outage only ever
189	/// costs the accelerator, never a validation.
190	pub struct RedisApiKeyCache {
191	    conn: ConnectionManager,
192	    ttl_secs: u64,
193	}
194	
195	impl RedisApiKeyCache {
196	    /// Opens `redis_url` and wraps it in a `ConnectionManager`. `ttl_secs` is applied to every
197	    /// `put` as Redis's own `EX` expiry — this cache is a fail-open accelerator, so an entry
198	    /// disappearing after `ttl_secs` (or on eviction) never surfaces as anything other than a
199	    /// subsequent miss.
200	    pub async fn connect(redis_url: &str, ttl_secs: u64) -> Result<Self, redis::RedisError> {
201	        let client = Client::open(redis_url)?;
202	        let conn = ConnectionManager::new(client).await?;
203	        Ok(Self { conn, ttl_secs })
204	    }
205	
206	    /// Builds a cache over an ALREADY-CONNECTED `ConnectionManager`: mirrors
207	    /// `RedisDecisionCache::from_connection`/`SliceCache::from_connection` (SMA-444 Task 21) —
208	    /// a future `AppState` wiring can share ONE redis connection across the redis-backed
209	    /// `Generations` + `RedisDecisionCache` + `SliceCache` + this cache rather than each
210	    /// opening its own; `connect` above stays the standalone-caller/test entry point.
211	    #[must_use]
212	    pub fn from_connection(conn: ConnectionManager, ttl_secs: u64) -> Self {
213	        Self { conn, ttl_secs }
214	    }
215	}
216	
217	#[async_trait]
218	impl ApiKeyValidationCache for RedisApiKeyCache {
219	    async fn get(&self, key_id: ApiKeyId) -> Option<CachedValidation> {
220	        let key = cache_key(key_id);
221	        let mut conn = self.conn.clone();
222	        let raw: Result<Option<Vec<u8>>, redis::RedisError> = conn.get(&key).await;
223	        match raw {
224	            Ok(Some(bytes)) => match serde_json::from_slice::<WireValidation>(&bytes).ok().and_then(|w| CachedValidation::try_from(w).ok()) {
225	                Some(v) => Some(v),
226	                None => {
227	                    log_deserialize_miss();
228	                    None
229	                }
230	            },
231	            Ok(None) => None,
232	            Err(err) => {
233	                log_get_miss(err.kind());
234	                None
235	            }
236	        }
237	    }
238	
239	    async fn put(&self, key_id: ApiKeyId, v: &CachedValidation) {
240	        let payload = match serde_json::to_vec(&WireValidation::from(v)) {
241	            Ok(payload) => payload,
242	            Err(_) => {
243	                log_serialize_swallow();
244	                return;
245	            }
246	        };
247	        let key = cache_key(key_id);
248	        let mut conn = self.conn.clone();
249	        let result: Result<(), redis::RedisError> = conn.set_ex(&key, payload, self.ttl_secs).await;
250	        if let Err(err) = result {
251	            log_put_swallow(err.kind());
252	        }
253	    }
254	
255	    async fn evict(&self, key_id: ApiKeyId) {
256	        let key = cache_key(key_id);
257	        let mut conn = self.conn.clone();
258	        let result: Result<(), redis::RedisError> = conn.del(&key).await;
259	        if let Err(err) = result {
260	            log_evict_swallow(err.kind());
261	        }
262	    }
263	}
264	
265	/// Logs the Redis error's `ErrorKind` only — never `Display`/message, which can echo
266	/// connection details (same posture as `oidc::redis_cache::log_unavailable` /
267	/// `decision_cache::log_get_miss`) — then the fail-open mapping: a get error degrades to a
268	/// plain miss (D5).
269	fn log_get_miss(kind: redis::ErrorKind) {
270	    tracing::warn!(error_kind = ?kind, "redis api key cache get error — treating as a miss (fail-open, D5)");
271	}
272	
273	fn log_deserialize_miss() {
274	    tracing::warn!(error_kind = "serde_json", "redis api key cache deserialize error — treating as a miss (fail-open, D5)");
275	}
276	
277	fn log_put_swallow(kind: redis::ErrorKind) {
278	    tracing::warn!(error_kind = ?kind, "redis api key cache put error — swallowed (fail-open, D5)");
279	}
280	
281	fn log_serialize_swallow() {
282	    tracing::warn!(error_kind = "serde_json", "redis api key cache serialize error — swallowed (fail-open, D5)");
283	}
284	
285	fn log_evict_swallow(kind: redis::ErrorKind) {
286	    tracing::warn!(error_kind = ?kind, "redis api key cache evict error — swallowed (fail-open, D5)");
287	}
288	
289	#[cfg(test)]
290	mod tests {
291	    use super::*;
292	    use uuid::Uuid;
293	
294	    fn pid() -> PrincipalId {
295	        let uuid = Uuid::from_u128(100);
296	        PrincipalId::from_prn(Prn::build("iam", "", None, "principal", uuid).expect("static test prn parts are valid"))
297	    }
298	
299	    fn sample_validation() -> CachedValidation {
300	        CachedValidation {
301	            principal_id: pid(),
302	            sa_status: PrincipalStatus::Active,
303	            expires_at: None,
304	            key_hash: vec![0xDE, 0xAD, 0xBE, 0xEF],
305	        }
306	    }
307	
308	    #[tokio::test]
309	    async fn memory_cache_put_get_evict() {
310	        let c = MemoryApiKeyCache::new(30);
311	        let id = ApiKeyId::from_uuid(Uuid::from_u128(9));
312	        assert!(c.get(id).await.is_none());
313	        c.put(id, &sample_validation()).await;
314	        assert!(c.get(id).await.is_some());
315	        c.evict(id).await;
316	        assert!(c.get(id).await.is_none());
317	    }
318	
319	    #[tokio::test]
320	    async fn memory_cache_get_round_trips_the_full_value() {
321	        let c = MemoryApiKeyCache::new(30);
322	        let id = ApiKeyId::from_uuid(Uuid::from_u128(1));
323	        let v = CachedValidation {
324	            principal_id: pid(),
325	            sa_status: PrincipalStatus::Disabled,
326	            expires_at: Some(Utc::now()),
327	            key_hash: vec![1, 2, 3, 4, 5],
328	        };
329	        c.put(id, &v).await;
330	        assert_eq!(c.get(id).await, Some(v));
331	    }
332	
333	    #[tokio::test]
334	    async fn memory_cache_entry_expires_after_its_ttl() {
335	        let c = MemoryApiKeyCache::new(0);
336	        let id = ApiKeyId::from_uuid(Uuid::from_u128(11));
337	        c.put(id, &sample_validation()).await;
338	        tokio::time::sleep(Duration::from_millis(20)).await;
339	        assert!(c.get(id).await.is_none(), "an entry past its TTL must be treated as a miss");
340	    }
341	
342	    #[tokio::test]
343	    async fn memory_cache_get_of_missing_key_is_none() {
344	        let c = MemoryApiKeyCache::new(30);
345	        assert!(c.get(ApiKeyId::from_uuid(Uuid::from_u128(404))).await.is_none());
346	    }
347	
348	    #[test]
349	    fn wire_validation_round_trips_through_json() {
350	        let v = CachedValidation {
351	            principal_id: pid(),
352	            sa_status: PrincipalStatus::Active,
353	            expires_at: Some(Utc::now()),
354	            key_hash: vec![0x00, 0xFF, 0x10, 0x20, 0x30],
355	        };
356	        let bytes = serde_json::to_vec(&WireValidation::from(&v)).unwrap();
357	        let wire: WireValidation = serde_json::from_slice(&bytes).unwrap();
358	        let round_tripped = CachedValidation::try_from(wire).unwrap();
359	        assert_eq!(round_tripped, v, "the stored key_hash must survive the base64 wire round-trip byte-for-byte");
360	    }
361	
362	    /// D5's fail-open contract, exercised without any live Redis (a lazily-connecting
363	    /// `ConnectionManager` never dials out — mirrors
364	    /// `entity_cache::load_fails_open_to_the_inner_loader_when_entity_gen_errors`): a `get`
365	    /// against an unreachable backend degrades to `None`, and `put`/`evict` never panic.
366	    #[tokio::test]
367	    async fn redis_cache_fails_open_when_the_backend_is_unreachable() {
368	        let client = Client::open("redis://127.0.0.1:1").expect("well-formed redis URL, never actually dialed");
369	        let conn = ConnectionManager::new_lazy_with_config(client, redis::aio::ConnectionManagerConfig::new()).expect("lazy ConnectionManager construction never connects");
370	        let cache = RedisApiKeyCache::from_connection(conn, 30);
371	        let id = ApiKeyId::from_uuid(Uuid::from_u128(12));
372	
373	        assert!(cache.get(id).await.is_none(), "an unreachable redis must degrade to a plain miss, not panic/error");
374	        cache.put(id, &sample_validation()).await;
375	        cache.evict(id).await;
376	    }
377	}
