1	// SPDX-License-Identifier: Apache-2.0
2	
3	//! Service configuration via figment: built-in defaults < `gateway.toml` < `GATEWAY_*` env.
4	
5	use figment::providers::{Env, Format, Serialized, Toml};
6	use figment::{Figment, error::Error as FigmentError};
7	use secrecy::{ExposeSecret, SecretString};
8	use serde::{Deserialize, Serialize};
9	use std::net::SocketAddr;
10	
11	/// M0 walking-skeleton config (see the module doc): one HTTP port, an IAM gRPC client
12	/// endpoint (G4 dials it), and the single OpenAI upstream (G6 calls out to it). No database,
13	/// no gRPC server of its own — mirrors `paigasus-iam::config::IamConfig`'s figment pattern
14	/// but is deliberately much smaller. Does NOT derive `PartialEq`: `upstream` transitively
15	/// carries `OpenAiConfig::api_key: SecretString`, which `secrecy` does not implement
16	/// `PartialEq` for (see `OpenAiConfig`'s doc).
17	#[derive(Debug, Clone, Deserialize, Serialize)]
18	pub struct GatewayConfig {
19	    pub http_addr: SocketAddr,
20	    pub connect_timeout_secs: u64,
21	    pub first_byte_timeout_secs: u64,
22	    pub stream_idle_timeout_secs: u64,
23	    pub max_request_bytes: usize,
24	    pub iam: IamClientConfig,
25	    pub upstream: UpstreamConfig,
26	    pub log_level: String,
27	}
28	
29	/// The IAM gRPC client endpoint G4 dials (`Introspect`/authorization calls). `tls` governs
30	/// how that channel is secured — see [`IamTlsConfig`]'s doc for the D8 rationale.
31	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
32	pub struct IamClientConfig {
33	    pub grpc_addr: String,
34	    pub tls: IamTlsConfig,
35	}
36	
37	/// D8: TLS is the default transport to `paigasus-iam`'s gRPC endpoint — the introspect call
38	/// carries raw caller-presented API keys, so the link must be encrypted unless an operator
39	/// EXPLICITLY opts into `loopback_insecure`, and even then only when `iam.grpc_addr` resolves
40	/// to a loopback host (checked in [`GatewayConfig::validate`] — `Deserialize` alone can't see
41	/// the sibling `grpc_addr` field to validate against). An enum (rather than a `bool` `enabled`
42	/// flag + always-present cert-path options) makes "insecure but cert paths configured" or
43	/// "secure but disabled" unrepresentable at the type level; G4 matches on this to build the
44	/// tonic channel.
45	#[derive(Debug, Clone, Deserialize, Serialize, PartialEq, Eq)]
46	#[serde(tag = "mode", rename_all = "snake_case")]
47	pub enum IamTlsConfig {
48	    Tls {
49	        /// Custom CA bundle to trust, in addition to (G4 decides: instead of, or alongside)
50	        /// the system trust store. `None` = system trust store only.
51	        #[serde(default)]
52	        ca_cert_path: Option<String>,
53	        /// mTLS client certificate. Must be set together with `client_key_path` or not at
54	        /// all — G4 validates that pairing when it builds the tonic channel.
55	        #[serde(default)]
56	        client_cert_path: Option<String>,
57	        #[serde(default)]
58	        client_key_path: Option<String>,
59	    },
60	    LoopbackInsecure,
61	}
62	
63	impl Default for IamClientConfig {
64	    fn default() -> Self {
65	        IamClientConfig {
66	            grpc_addr: "https://127.0.0.1:9090".to_string(),
67	            tls: IamTlsConfig::default(),
68	        }
69	    }
70	}
71	
72	impl Default for IamTlsConfig {
73	    fn default() -> Self {
74	        IamTlsConfig::Tls {
75	            ca_cert_path: None,
76	            client_cert_path: None,
77	            client_key_path: None,
78	        }
79	    }
80	}
81	
82	/// Outbound upstream(s) the gateway calls on the caller's behalf. Only OpenAI today (G6 is
83	/// the first consumer) — a future upstream would add a sibling field here.
84	#[derive(Debug, Clone, Deserialize, Serialize)]
85	pub struct UpstreamConfig {
86	    pub openai: OpenAiConfig,
87	}
88	
89	/// The OpenAI egress target (G6 consumes this to build the outbound client).
90	#[derive(Debug, Clone, Deserialize, Serialize)]
91	pub struct OpenAiConfig {
92	    pub base_url: String,
93	    /// Sourced from `GATEWAY_UPSTREAM__OPENAI__API_KEY`, never from `gateway.toml` (see
94	    /// `gateway.toml.example`). `#[serde(skip_serializing)]` so a config log/`readyz` dump
95	    /// (`GatewayConfig` derives `Serialize`) never emits it; `SecretString`'s own `Debug`
96	    /// already redacts it for the derived `Debug` path — mirrors iam's `RawPepper` redaction
97	    /// posture, but `secrecy`'s `serde` feature already supplies `Deserialize` for
98	    /// `SecretString`, so no hand-rolled newtype is needed here.
99	    #[serde(skip_serializing)]
100	    pub api_key: SecretString,
101	}
102	
103	// Only the fields that HAVE a default — every `GatewayConfig` field has one (unlike iam's
104	// `database_url`/`authn.issuers`, nothing here is a hard-required, default-less value).
105	#[derive(Serialize)]
106	struct Defaults {
107	    http_addr: SocketAddr,
108	    connect_timeout_secs: u64,
109	    first_byte_timeout_secs: u64,
110	    stream_idle_timeout_secs: u64,
111	    max_request_bytes: usize,
112	    iam: IamClientConfig,
113	    upstream: UpstreamDefaults,
114	    log_level: String,
115	}
116	
117	#[derive(Serialize, Default)]
118	struct UpstreamDefaults {
119	    openai: OpenAiDefaults,
120	}
121	
122	// Mirrors `OpenAiConfig` field-for-field, EXCEPT `api_key`'s TYPE: this struct only ever
123	// feeds figment's default LAYER (`Serialized::defaults`), never gets logged/dumped itself, so
124	// a plain (unredacted) `String` is fine here — figment still deserializes the eventual merged
125	// value into `OpenAiConfig.api_key: SecretString` regardless of which layer (default/toml/env)
126	// supplied it. The default is the empty string, deliberately INVALID (an empty key can never
127	// authenticate to OpenAI) — caught by `GatewayConfig::validate` rather than at figment
128	// extraction, mirroring iam's `ApiKeyDefaults`/`RawPepper` pattern exactly.
129	#[derive(Serialize)]
130	struct OpenAiDefaults {
131	    base_url: String,
132	    api_key: String,
133	}
134	
135	impl Default for Defaults {
136	    fn default() -> Self {
137	        Defaults {
138	            http_addr: "0.0.0.0:8088".parse().expect("valid addr"),
139	            connect_timeout_secs: 10,
140	            first_byte_timeout_secs: 30,
141	            stream_idle_timeout_secs: 300,
142	            max_request_bytes: 1_048_576, // 1 MiB
143	            iam: IamClientConfig::default(),
144	            upstream: UpstreamDefaults::default(),
145	            log_level: "info".to_string(),
146	        }
147	    }
148	}
149	
150	impl Default for OpenAiDefaults {
151	    fn default() -> Self {
152	        OpenAiDefaults {
153	            base_url: "https://api.openai.com".to_string(),
154	            api_key: String::new(),
155	        }
156	    }
157	}
158	
159	/// True when `grpc_addr`'s host is a loopback address (`127.0.0.0/8`, `localhost`, `::1`).
160	/// Deliberately a small hand-rolled parser rather than pulling in a `url` crate dependency
161	/// for a single boot-time check: `grpc_addr` is `scheme://host[:port]`, optionally with a
162	/// trailing path; strip the scheme, strip any path, then split the host from an optional
163	/// port (bracketed for IPv6 literals).
164	fn is_loopback_host(grpc_addr: &str) -> bool {
165	    let after_scheme = grpc_addr.split("://").last().unwrap_or(grpc_addr);
166	    let host_port = after_scheme.split('/').next().unwrap_or(after_scheme);
